"use client";

import * as Tabs from "@radix-ui/react-tabs";
import {
  Activity, ArrowRight, Banknote, Boxes, Brain, ExternalLink,
  Cloud, CloudOff, FlaskConical, Gauge, History, LoaderCircle, MessageSquareText, Network,
  Radar, RefreshCw, Save, ShieldAlert, Sparkles, Users,
} from "lucide-react";
import Link from "next/link";
import { useCallback, useEffect, useMemo, useState } from "react";
import type { AiDialogueResponse, SimulationCommand } from "@sim/engine";
import type { ClientRunRecord, CommandRequest, CommandResponse } from "@/server/store/types";
import { cn, money, number } from "@/lib/ui";

type PendingRecord = CommandRequest & { runId: string };
type SaveStatus = "saved" | "saving" | "offline" | "conflict";

const DB_NAME = "founderos-command-queue";
const STORE = "pending";
function queueDb() { return new Promise<IDBDatabase>((resolve, reject) => { const request = indexedDB.open(DB_NAME, 1); request.onupgradeneeded = () => { if (!request.result.objectStoreNames.contains(STORE)) request.result.createObjectStore(STORE, { keyPath: "runId" }); }; request.onsuccess = () => resolve(request.result); request.onerror = () => reject(request.error); }); }
async function putPending(record: PendingRecord) { const db = await queueDb(); await new Promise<void>((resolve, reject) => { const tx = db.transaction(STORE, "readwrite"); tx.objectStore(STORE).put(record); tx.oncomplete = () => resolve(); tx.onerror = () => reject(tx.error); }); db.close(); }
async function readPending(runId: string) { const db = await queueDb(); const value = await new Promise<PendingRecord | undefined>((resolve, reject) => { const request = db.transaction(STORE).objectStore(STORE).get(runId); request.onsuccess = () => resolve(request.result); request.onerror = () => reject(request.error); }); db.close(); return value; }
async function deletePending(runId: string) { const db = await queueDb(); await new Promise<void>((resolve, reject) => { const tx = db.transaction(STORE, "readwrite"); tx.objectStore(STORE).delete(runId); tx.oncomplete = () => resolve(); tx.onerror = () => reject(tx.error); }); db.close(); }

const tabs = [
  ["situation", "Situation", Activity], ["evidence", "Evidence", FlaskConical], ["product", "Product", Boxes],
  ["people", "People", Users], ["ledger", "Ledger", Banknote], ["strategy", "Strategy", Brain], ["advanced", "Advanced", Gauge],
] as const;
const stages = ["discovery", "validation", "pilot", "productization", "repeatability"] as const;

function Panel({ title, subtitle, children, className }: { title: string; subtitle?: string; children: React.ReactNode; className?: string }) {
  return <section className={cn("surface p-4 sm:p-5", className)}><div><h2 className="font-black">{title}</h2>{subtitle && <p className="muted mt-1 text-xs leading-5">{subtitle}</p>}</div><div className="mt-4">{children}</div></section>;
}
function Progress({ value, tone = "good" }: { value: number; tone?: "good" | "warn" | "bad" }) {
  return <div className="h-2 overflow-hidden rounded-full bg-black/30"><div className={cn("h-full rounded-full", tone === "good" ? "bg-emerald-300" : tone === "warn" ? "bg-amber-300" : "bg-red-400")} style={{ width: `${Math.max(0, Math.min(100, value))}%` }} /></div>;
}
function Estimate({ label, low, expected, high, confidence }: { label: string; low: number; expected: number; high: number; confidence: string }) {
  return <div className="surface-soft p-3"><div className="flex items-center justify-between"><span className="muted text-xs">{label}</span><span className="pill">{confidence} confidence</span></div><div className="mt-2 text-xl font-black">{number(expected, 1)}</div><div className="faint mt-1 text-[11px]">Range {number(low, 1)}–{number(high, 1)}</div></div>;
}

export function RunWorkspace({ initialRun }: { initialRun: ClientRunRecord }) {
  const [state, setState] = useState(initialRun.state);
  const [version, setVersion] = useState(initialRun.stateVersion);
  const [checksum, setChecksum] = useState(initialRun.checksum);
  const [status, setStatus] = useState<SaveStatus>("saved");
  const [error, setError] = useState("");
  const [selectedProblem, setSelectedProblem] = useState(initialRun.state.problems.find((problem) => problem.status === "open")?.id ?? "");
  const [selectedSegment, setSelectedSegment] = useState(initialRun.state.market.segments[0]?.id ?? "");
  const [dialogueText, setDialogueText] = useState("");
  const [dialogue, setDialogue] = useState<AiDialogueResponse | null>(null);
  const [dialoguePending, setDialoguePending] = useState(false);
  const isV7 = state.engineVersion.startsWith("7.");
  const [researchQuestion, setResearchQuestion] = useState<"severity" | "workflow" | "budget" | "buyer">("severity");
  const [researchSample, setResearchSample] = useState<"cold_targeted" | "existing_users" | "warm_network" | "convenience">("cold_targeted");
  const [researchMethod, setResearchMethod] = useState<"interview" | "observation" | "proposal" | "survey">("interview");
  const [researchCount, setResearchCount] = useState(8);
  const [actionIntensity, setActionIntensity] = useState<"sustainable" | "hard" | "crunch">("sustainable");
  const [productApproach, setProductApproach] = useState<"prototype" | "production" | "accept_debt">("prototype");
  const [selectedCapability, setSelectedCapability] = useState(initialRun.state.product.capabilities.find((item) => item.status === "backlog")?.id ?? "");
  const [dealPrice, setDealPrice] = useState(initialRun.state.market.defaultPrice);
  const [dealMonths, setDealMonths] = useState(3);
  const [dealPrepay, setDealPrepay] = useState(false);
  const [paymentTerms, setPaymentTerms] = useState<0 | 15 | 30 | 60>(30);
  const [onboardingMode, setOnboardingMode] = useState<"self_serve" | "guided" | "custom">("guided");
  const [supportSla, setSupportSla] = useState<8 | 24 | 72>(24);
  const [dataTerms, setDataTerms] = useState<"standard" | "dpa" | "enterprise">("standard");
  const [financeAmount, setFinanceAmount] = useState(100);
  const [peopleRole, setPeopleRole] = useState<"engineer" | "product" | "sales" | "operations">("engineer");
  const [peopleMode, setPeopleMode] = useState<"hire" | "contract" | "advisor">("contract");
  const [peopleBudget, setPeopleBudget] = useState(900);

  const active = state.actions.filter((action) => action.status === "active");
  const openProblems = state.problems.filter((problem) => problem.status === "open").sort((a, b) => b.severity - a.severity);
  const selected = state.problems.find((problem) => problem.id === selectedProblem) ?? openProblems[0];
  const attentionCapacity = state.organization.members.reduce((sum, member) => sum + member.capacity * (member.onboardingRemaining > 0 ? 0.35 : 1), 0);
  const attention = active.reduce((sum, action) => sum + action.attention, 0) / Math.max(1, attentionCapacity);
  const personalRunway = state.finance.livingCost ? state.finance.personalCash / state.finance.livingCost : 99;
  const backlogCapability = state.product.capabilities.find((capability) => capability.status === "backlog");
  const capabilityChoice = state.product.capabilities.find((capability) => capability.id === selectedCapability && capability.status === "backlog") ?? backlogCapability;
  const actionableAccount = state.market.accounts.find((account) => !["customer", "lost", "churned"].includes(account.stage));
  const accountStakeholders = actionableAccount ? state.stakeholders.filter((stakeholder) => stakeholder.accountId === actionableAccount.id) : [];
  const actorId = state.pendingEvent?.actorId ?? state.stakeholders[0]?.id;
  const intelligence = state.features?.public["market-intelligence"];
  const competitorWorld = state.features?.public.competitors;
  const pendingAgentTurn = competitorWorld?.pendingTurn;

  const execute = useCallback(async (record: PendingRecord, fromQueue = false) => {
    setStatus("saving"); setError(""); if (!fromQueue) await putPending(record);
    try {
      const response = await fetch(`/api/v1/runs/${record.runId}/commands`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ commandId: record.commandId, expectedVersion: record.expectedVersion, type: record.type, payload: record.payload }) });
      const body = await response.json();
      if (response.status === 409 && body.error === "VERSION_CONFLICT") {
        const canonical = await fetch(`/api/v1/runs/${record.runId}`).then((item) => item.json());
        if (canonical.run) { setState(canonical.run.state); setVersion(canonical.run.stateVersion); setChecksum(canonical.run.checksum); }
        await deletePending(record.runId); setStatus("conflict"); setError("Another state version was saved. The canonical cloud state has been reloaded."); return;
      }
      if (!response.ok) { await deletePending(record.runId); setStatus("saved"); setError(body.error ?? "The command was rejected."); return; }
      const result = body as CommandResponse; setState(result.state); setVersion(result.version); setChecksum(result.checksum); setDialogue(null); await deletePending(record.runId); setStatus("saved");
    } catch { setStatus("offline"); setError("Network unavailable. This decision is queued locally; further mutations are locked until it is confirmed."); }
  }, []);

  useEffect(() => { readPending(initialRun.id).then((record) => { if (record) void execute(record, true); }).catch(() => undefined); }, [execute, initialRun.id]);
  useEffect(() => {
    if (!pendingAgentTurn) return;
    const timer = window.setInterval(async () => {
      try {
        const response = await fetch(`/api/v1/runs/${initialRun.id}`, { cache: "no-store" }); const body = await response.json();
        if (response.ok && body.run?.stateVersion > version) {
          setState(body.run.state); setVersion(body.run.stateVersion); setChecksum(body.run.checksum); setStatus("saved");
        }
      } catch { /* Autosave remains canonical; the next poll can recover. */ }
    }, 1_200);
    return () => window.clearInterval(timer);
  }, [initialRun.id, pendingAgentTurn, version]);
  async function command(type: SimulationCommand["type"], payload: unknown) {
    if (status === "saving" || status === "offline") return;
    if (pendingAgentTurn) { setError("A critical competitor turn is resolving. The deterministic fallback releases the world within six seconds."); return; }
    await execute({ runId: initialRun.id, commandId: crypto.randomUUID(), expectedVersion: version, type, payload });
  }
  async function askStakeholder() {
    if (!state.pendingEvent || !actorId || !dialogueText.trim()) return;
    setDialoguePending(true); setError("");
    try {
      const response = await fetch(`/api/v1/runs/${initialRun.id}/dialogue`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ interactionId: state.pendingEvent.id, actorId, message: dialogueText }) });
      const body = await response.json(); if (!response.ok) throw new Error(body.error ?? "DIALOGUE_FAILED");
      setDialogue(body.turn.response); setDialogueText("");
    } catch (cause) { setError(cause instanceof Error ? cause.message : "DIALOGUE_FAILED"); }
    finally { setDialoguePending(false); }
  }

  const saveCopy = { saved: [Save, "Cloud saved"], saving: [LoaderCircle, "Saving command…"], offline: [CloudOff, "Offline — queued"], conflict: [RefreshCw, "Cloud state reloaded"] } as const;
  const SaveIcon = saveCopy[status][0];
  const pipeline = useMemo(() => ["lead", "discovery", "qualified", "pilot", "negotiation", "customer"].map((stage) => ({ stage, count: state.market.accounts.filter((account) => account.stage === stage).length })), [state.market.accounts]);

  return <div className="min-h-screen pb-28 lg:pb-24">
    <header className="border-b border-white/7 bg-[#071019]/78 backdrop-blur-xl"><div className="container-page py-5">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><div className="flex flex-wrap items-center gap-2"><span className={cn("pill", state.status === "active" ? "pill-good" : "pill-bad")}>{state.status}</span><span className="pill capitalize">{state.stage}</span><span className="pill">Day {state.calendar.absoluteDay}</span><span className="pill">{state.meta.vertical}</span></div><h1 className="mt-3 text-2xl font-black tracking-tight sm:text-3xl">{state.meta.companyName}</h1><p className="muted mt-1 text-xs">{state.scenarioVersion} · engine {state.engineVersion} · decision {state.decisionPoints}</p></div><div className="flex flex-wrap items-center gap-2"><span className={cn("pill", status === "offline" ? "pill-bad" : status === "conflict" ? "pill-warn" : "pill-good")}><SaveIcon className={status === "saving" ? "animate-spin" : ""} size={13} />{saveCopy[status][1]}</span><Link href={`/runs/${initialRun.id}/history`} className="btn btn-secondary"><History size={15} />History</Link>{state.status !== "active" && <Link href={`/runs/${initialRun.id}/debrief`} className="btn btn-primary">Open debrief</Link>}</div></div>
      <div className="mt-5 flex items-center gap-1">{stages.map((stage, index) => <div className="min-w-0 flex-1" key={stage}><div className={cn("h-1.5 rounded-full", index <= stages.indexOf(state.stage) ? "bg-emerald-300" : "bg-slate-700")} /><div className={cn("mt-1 hidden truncate text-[10px] capitalize sm:block", stage === state.stage ? "text-emerald-300" : "faint")}>{stage}</div></div>)}</div>
      <div className="metric-grid mt-5"><div className="metric-card"><div className="metric-label">Company cash</div><div className={cn("metric-value", state.finance.companyCash < 120 && "text-red-300")}>{money(state.finance.companyCash)}</div><div className="metric-note">AR {money(state.finance.accountsReceivable)} · MRR {money(state.finance.mrr)}</div></div><div className="metric-card"><div className="metric-label">Personal runway</div><div className={cn("metric-value", personalRunway < 1 && "text-red-300")}>{number(personalRunway, 1)} mo</div><div className="metric-note">Living {money(state.finance.livingCost)}/mo</div></div><div className="metric-card"><div className="metric-label">Attention load</div><div className={cn("metric-value", attention > 1.15 && "text-red-300")}>{number(attention, 2)}×</div><div className="metric-note">{active.length} commitments · stress {number(state.founder.stress)}%</div></div><div className="metric-card"><div className="metric-label">Evidence confidence</div><div className="metric-value">{state.forecasts.pmfReadiness.confidence}</div><div className="metric-note">PMF estimate {number(state.forecasts.pmfReadiness.low)}–{number(state.forecasts.pmfReadiness.high)}</div></div></div>
    </div></header>

    {error && <div className="container-page mt-4"><div role="alert" className="flex items-start gap-2 rounded-xl border border-amber-300/25 bg-amber-300/8 p-3 text-sm text-amber-100"><ShieldAlert className="mt-0.5 shrink-0" size={16} /><span>{error}</span>{status === "offline" && <button className="ml-auto font-bold underline" onClick={() => readPending(initialRun.id).then((record) => record && execute(record, true))}>Retry</button>}</div></div>}

    {state.pendingEvent && <div className="container-page mt-4"><div className="surface border-amber-300/30 p-5"><div className="eyebrow text-amber-300">Decision required · causal pressure: {state.pendingEvent.pressure}</div><h2 className="mt-2 text-xl font-black">{state.pendingEvent.title}</h2><p className="muted mt-2 text-sm leading-6">{state.pendingEvent.summary}</p>
      {actorId && !isV7 && <div className="mt-4 rounded-xl border border-sky-300/20 bg-sky-300/5 p-4"><div className="flex items-center gap-2 text-sm font-bold"><MessageSquareText size={16} className="text-sky-300" />Ask the stakeholder before committing</div>{dialogue && <div className="mt-3 rounded-lg bg-black/20 p-3"><p className="text-sm leading-6">“{dialogue.utterance}”</p><div className="faint mt-2 text-xs">Tone: {dialogue.tone} · candidate intent: {dialogue.interpretedIntentId ?? "unclear"}</div></div>}<div className="mt-3 flex gap-2"><input className="input" value={dialogueText} maxLength={800} onChange={(event) => setDialogueText(event.target.value)} placeholder="Ask a focused question or propose a response…" /><button className="btn btn-secondary shrink-0" disabled={dialoguePending || !dialogueText.trim()} onClick={askStakeholder}>{dialoguePending ? <LoaderCircle className="animate-spin" size={15} /> : <MessageSquareText size={15} />}Ask</button></div><p className="faint mt-2 text-[11px]">AI interprets dialogue only. You must confirm one engine-defined decision below.</p></div>}
      <div className="mt-4 grid gap-2 lg:grid-cols-3">{state.pendingEvent.choices.map((choice, index) => <button key={choice.id} className="surface-soft p-4 text-left transition hover:border-emerald-300/40" disabled={status !== "saved"} onClick={() => command("event.respond", { choiceIndex: index })}><div className="font-bold">{choice.label}</div><div className="muted mt-2 text-xs leading-5">{choice.tradeoff}</div></button>)}</div>
    </div></div>}

    <div className="container-page py-5"><Tabs.Root defaultValue="situation"><Tabs.List className="flex gap-1 overflow-x-auto rounded-xl border border-white/7 bg-black/15 p-1" aria-label="Simulation views">{tabs.map(([value, label, Icon]) => <Tabs.Trigger key={value} value={value} className="flex shrink-0 items-center gap-2 rounded-lg px-3 py-2 text-xs font-bold text-slate-400 data-[state=active]:bg-slate-700/70 data-[state=active]:text-white"><Icon size={14} />{label}</Tabs.Trigger>)}</Tabs.List>
      <div className="mt-4 grid gap-4 xl:grid-cols-[minmax(0,1fr)_340px]"><main className="min-w-0">
        <Tabs.Content value="situation" className="space-y-4">
          <Panel title="Decision brief" subtitle="Ranges reflect what the founder can currently know; canonical market truth stays on the server."><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Estimate label="Runway · months" {...state.forecasts.runwayMonths} /><Estimate label="Next-month cash" {...state.forecasts.nextMonthCash} /><Estimate label="Pipeline revenue" {...state.forecasts.pipelineRevenue} /><Estimate label="PMF readiness" {...state.forecasts.pmfReadiness} /></div></Panel>
          <Panel title="Problem board" subtitle="Issues improve only when their causal drivers change."><div className="grid gap-3">{openProblems.length ? openProblems.map((problem) => <button key={problem.id} onClick={() => setSelectedProblem(problem.id)} className={cn("surface-soft w-full p-4 text-left transition", selected?.id === problem.id && "border-emerald-300/40 bg-emerald-300/5")}><div className="flex items-start justify-between gap-3"><div><div className="flex items-center gap-2"><span className={cn("size-2 rounded-full", problem.severity >= 4 ? "bg-red-400" : "bg-amber-300")} /><h3 className="font-bold">{problem.title}</h3></div><p className="muted mt-2 text-sm leading-5">{problem.summary}</p></div><span className={cn("pill", problem.severity >= 4 ? "pill-bad" : "pill-warn")}>{problem.severity}/5</span></div><div className="mt-3 flex flex-wrap gap-2 text-xs"><span className="faint">Deadline day {problem.deadlineDay}</span><span className={cn("pill", problem.trajectory === "improving" ? "pill-good" : problem.trajectory === "worsening" ? "pill-bad" : "pill-warn")}>{problem.trajectory}</span><span className="pill">resolution {number(problem.resolutionProgress ?? 0)}%</span></div></button>) : <div className="muted text-sm">All current causal issues are resolved.</div>}</div></Panel>
          <Panel title="Account funnel" subtitle="Progress requires committee access, a credible value case, implementation readiness, risk clearance, and procurement—not a flat conversion bonus.">
            <div className="grid grid-cols-3 gap-2 sm:grid-cols-6">{pipeline.map((item) => <div className="surface-soft p-3 text-center" key={item.stage}><div className="text-xl font-black">{item.count}</div><div className="faint mt-1 text-[10px] capitalize">{item.stage}</div></div>)}</div>
            <div className="mt-4 space-y-2">{state.market.accounts.slice(-8).reverse().map((account) => <div className="surface-soft flex flex-col gap-3 p-3 sm:flex-row sm:items-center sm:justify-between" key={account.id}><div><div className="text-sm font-bold">{account.name}</div><div className="faint mt-1 text-xs">{account.stage} · EV {money(account.expectedValue)} · trust {number(account.trust)} · committee {number(account.committeeCoverage ?? 0)}%</div><div className="faint mt-1 text-[10px]">Value {number(account.valueCase ?? 0)} · implementation {number(account.implementationReadiness ?? 0)} · risk {number(account.riskClearance ?? 0)} · procurement {number(account.procurementProgress ?? 0)}</div></div><div className="flex gap-2">{!["lost", "customer", "churned", "negotiation"].includes(account.stage) && <button className="btn btn-secondary !min-h-9 !px-3" disabled={status !== "saved"} onClick={() => command("account.manage", { operation: "advance", accountId: account.id })}>Generic follow-up</button>}{account.stage === "negotiation" && <span className="pill pill-warn">Configure terms in Decision Studio</span>}</div></div>)}</div>
          </Panel>
          {actionableAccount && !isV7 && <Panel title="Buying committee" subtitle={`${actionableAccount.name} · targeted conversations change different causal gates.`}>
            <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-5">{accountStakeholders.map((stakeholder) => <div className="surface-soft p-3" key={stakeholder.id}><div className="text-sm font-bold">{stakeholder.name}</div><div className="faint mt-1 text-xs capitalize">{stakeholder.role} · influence {number(stakeholder.influence)} · trust {number(stakeholder.trust)}</div></div>)}</div>
            <div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{[
              ["map_committee", "Map decision committee"], ["user_discovery", "Observe user workflow"], ["build_champion", "Enable internal champion"],
              ["prove_roi", "Build economic case"], ["risk_review", "Run risk review"], ["procurement", "Navigate procurement"],
            ].map(([intent, label]) => <button key={intent} className="btn btn-secondary !justify-start" disabled={status !== "saved" || state.scheduledEffects.some((effect) => effect.type === "account_followup" && effect.sourceId === actionableAccount.id)} onClick={() => command("account.engage_stakeholder", { accountId: actionableAccount.id, intent })}>{label}</button>)}</div>
          </Panel>}
        </Tabs.Content>

        <Tabs.Content value="evidence" className="space-y-4"><div className="grid gap-4 md:grid-cols-2"><Panel title="Evidence quality"><div className="space-y-4">{[["Problem severity", state.evidence.problem], ["Budget evidence", state.evidence.budget], ["Buyer clarity", state.evidence.buyerClarity], ["Sample quality", state.evidence.quality], ["Design diversity", state.evidence.diversity]].map(([label, value]) => <div key={label as string}><div className="mb-2 flex justify-between text-xs"><span className="muted">{label}</span><strong>{number(value as number)}/100</strong></div><Progress value={value as number} /></div>)}</div></Panel><Panel title="Claims, not one magic score"><div className="space-y-3">{state.evidence.claims.map((claim) => <div key={claim.id}><div className="mb-1 flex justify-between gap-3 text-xs"><span>{claim.label}</span><strong>{number(claim.confidence)}%</strong></div><Progress value={claim.confidence} tone={claim.contradictingWeight > claim.supportingWeight ? "warn" : "good"} /><div className="faint mt-1 text-[10px]">{claim.sampleDiversity} independent clusters · last signal day {claim.lastUpdatedDay}</div></div>)}</div></Panel></div><Panel title="Evidence ledger" subtitle="Provenance, usable samples, independence, and contradictions remain visible."><div className="space-y-2">{state.evidence.ledger.length ? state.evidence.ledger.map((item) => <div className="surface-soft p-3" key={item.id}><div className="flex justify-between gap-3"><strong className="text-sm">{item.summary}</strong><span className={cn("pill", item.direction === "positive" ? "pill-good" : item.direction === "negative" ? "pill-bad" : "")}>{item.direction}</span></div><div className="faint mt-2 text-xs">Day {item.day} · {item.method ?? item.kind} · usable {item.usableSample ?? "—"}/{item.sampleSize ?? "—"} · cluster {item.independenceCluster ?? "legacy"}</div></div>) : <div className="muted text-sm">No evidence has been collected yet.</div>}</div></Panel></Tabs.Content>

        <Tabs.Content value="product" className="space-y-4"><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{[["Reliability", state.product.reliability, "good"], ["Usability", state.product.usability, "good"], ["Security", state.product.security, state.product.security < 30 ? "bad" : "warn"], ["Technical debt", state.product.technicalDebt, state.product.technicalDebt > 55 ? "bad" : "warn"]].map(([label, value, tone]) => <Panel key={label as string} title={label as string}><div className="text-2xl font-black">{number(value as number)}%</div><div className="mt-3"><Progress value={value as number} tone={tone as "good" | "warn" | "bad"} /></div></Panel>)}</div><Panel title="Capability dependency graph" subtitle="Shipping before dependencies are ready creates rework and debt."><div className="grid gap-3 md:grid-cols-2">{state.product.capabilities.map((capability) => <div className="surface-soft p-4" key={capability.id}><div className="flex items-start justify-between gap-2"><div><div className="font-bold">{capability.label}</div><div className="faint mt-1 text-xs">{capability.kind} · effort {capability.effort}</div></div><span className={cn("pill", capability.status === "released" ? "pill-good" : capability.status === "building" ? "pill-warn" : "")}>{capability.status}</span></div><div className="muted mt-3 text-xs">Depends on: {capability.dependencies.length ? capability.dependencies.join(", ") : "none"}</div></div>)}</div></Panel><Panel title="Incident response" subtitle="Containment protects the present; root-cause work consumes more capacity but reduces recurrence."><div className="grid gap-3 md:grid-cols-2">{state.product.incidents.length ? state.product.incidents.slice().reverse().map((incident) => <div className="surface-soft p-4" key={incident.id}><div className="flex items-center justify-between"><strong className="capitalize">{incident.type} incident</strong><span className={cn("pill", incident.status === "resolved" ? "pill-good" : "pill-bad")}>{incident.status}</span></div><div className="faint mt-1 text-xs">Opened day {incident.openedDay} · severity {incident.severity}/5</div>{incident.status !== "resolved" && <div className="mt-3 grid grid-cols-2 gap-2"><button className="btn btn-secondary !min-h-8 text-xs" disabled={status !== "saved"} onClick={() => command("incident.handle", { incidentId: incident.id, response: "contain" })}>Contain</button><button className="btn btn-secondary !min-h-8 text-xs" disabled={status !== "saved"} onClick={() => command("incident.handle", { incidentId: incident.id, response: "communicate" })}>Communicate</button><button className="btn btn-primary !min-h-8 text-xs" disabled={status !== "saved"} onClick={() => command("incident.handle", { incidentId: incident.id, response: "fix_root" })}>Fix root cause</button><button className="btn btn-secondary !min-h-8 text-xs" disabled={status !== "saved"} onClick={() => command("incident.handle", { incidentId: incident.id, response: "accept_risk" })}>Accept risk</button></div>}</div>) : <p className="muted text-sm">No product incidents have materialized.</p>}</div></Panel></Tabs.Content>

        <Tabs.Content value="people" className="space-y-4"><div className="grid gap-4 md:grid-cols-2"><Panel title="Founder operating condition"><div className="space-y-4">{[["Energy", state.founder.energy, "good"], ["Health", state.founder.health, "good"], ["Burnout", state.founder.burnout, state.founder.burnout > 65 ? "bad" : "warn"], ["Stress", state.founder.stress, state.founder.stress > 70 ? "bad" : "warn"]].map(([label, value, tone]) => <div key={label as string}><div className="mb-2 flex justify-between text-xs"><span>{label}</span><strong>{number(value as number)}%</strong></div><Progress value={value as number} tone={tone as "good" | "warn" | "bad"} /></div>)}</div></Panel><Panel title="Team and hiring"><div className="space-y-2">{state.organization.members.map((member) => <div className="surface-soft p-3" key={member.id}><div className="flex justify-between"><strong className="text-sm">{member.name}</strong><span className="pill">{member.employment}</span></div><div className="faint mt-1 text-xs">{member.role} · capacity {number(member.capacity)} · morale {number(member.morale)} · onboarding {member.onboardingRemaining}d</div></div>)}</div></Panel></div><Panel title="Obligations and stakeholder memory"><div className="grid gap-2 md:grid-cols-2">{state.obligations.length ? state.obligations.map((obligation) => <div className="surface-soft p-3" key={obligation.id}><div className="font-bold text-sm">{obligation.title}</div><div className="faint mt-1 text-xs">Due day {obligation.dueDay} · {obligation.status}</div>{obligation.status === "open" && <div className="mt-3 flex gap-2"><button className="btn btn-secondary !min-h-8 !px-2 text-xs" onClick={() => command("obligation.manage", { obligationId: obligation.id, operation: "fulfill" })}>Fulfill</button><button className="btn btn-secondary !min-h-8 !px-2 text-xs" onClick={() => command("obligation.manage", { obligationId: obligation.id, operation: "renegotiate" })}>Renegotiate</button></div>}</div>) : <p className="muted text-sm">No explicit obligations yet.</p>}</div></Panel></Tabs.Content>

        <Tabs.Content value="ledger" className="space-y-4"><div className="grid gap-4 md:grid-cols-2"><Panel title="Company position"><dl className="space-y-3 text-sm">{[["Cash", money(state.finance.companyCash)], ["Accounts receivable", money(state.finance.accountsReceivable)], ["Deferred revenue", money(state.finance.deferredRevenue)], ["MRR", money(state.finance.mrr)], ["Recognized revenue", money(state.finance.recognizedRevenue)], ["Founder loan", money(state.finance.founderLoanBalance)], ["Debt", money(state.capital.debt)]].map(([label, value]) => <div className="flex justify-between" key={label}><dt className="muted">{label}</dt><dd className="font-bold">{value}</dd></div>)}</dl></Panel><Panel title="Founder position"><dl className="space-y-3 text-sm"><div className="flex justify-between"><dt className="muted">Personal cash</dt><dd className="font-bold">{money(state.finance.personalCash)}</dd></div><div className="flex justify-between"><dt className="muted">Living cost</dt><dd className="font-bold">{money(state.finance.livingCost)}/mo</dd></div><div className="flex justify-between"><dt className="muted">Personal debt</dt><dd className="font-bold">{money(state.finance.personalDebt)}</dd></div></dl><label className="label mt-5" htmlFor="founderDraw">Founder draw per month</label><div className="flex gap-2"><input id="founderDraw" className="input" type="number" min="0" max={Math.max(0, state.finance.companyCash)} defaultValue={state.finance.founderDraw} /><button className="btn btn-secondary" onClick={() => { const value = Number((document.getElementById("founderDraw") as HTMLInputElement)?.value); void command("planning.update", { key: "founderDraw", value }); }}>Apply</button></div></Panel></div><Panel title="Double-entry journal" subtitle="Cash, receivables, liabilities, and revenue are posted separately."><div className="space-y-2">{state.finance.journal.slice(-20).reverse().map((entry) => <div className="surface-soft p-3" key={entry.id}><div className="flex justify-between gap-3"><strong className="text-sm">{entry.memo}</strong><span className="faint text-xs">Day {entry.day}</span></div><div className="mt-2 grid gap-1 text-[11px] sm:grid-cols-2">{entry.lines.map((line, index) => <div className="faint" key={`${entry.id}:${index}`}>{line.account}: Dr {money(line.debit)} · Cr {money(line.credit)}</div>)}</div></div>)}</div></Panel></Tabs.Content>

        <Tabs.Content value="strategy" className="space-y-4">
          {intelligence && competitorWorld && <Panel title="Intelligence Center" subtitle="Verified public facts inform the world. Competitor actions below are simulated and never presented as real-company behavior.">
            <div className="flex flex-wrap items-center gap-2"><span className="pill pill-good"><Radar size={13} />Dynamic world</span><span className="pill">Dossier {intelligence.dossier.capturedAt.slice(0, 10)}</span><span className="pill">{intelligence.dossier.facts.filter((fact) => fact.status === "verified").length} cited facts</span>{intelligence.dossier.facts.some((fact) => fact.status === "quarantined") && <span className="pill pill-warn">{intelligence.dossier.facts.filter((fact) => fact.status === "quarantined").length} quarantined</span>}{pendingAgentTurn && <span className="pill pill-warn"><LoaderCircle className="animate-spin" size={13} />Competitor turn resolving</span>}</div>
            <div className="mt-4 grid gap-3 lg:grid-cols-2">{competitorWorld.profiles.map((profile) => {
              const facts = intelligence.dossier.facts.filter((fact) => fact.subjectId === profile.id && fact.status === "verified");
              return <article className="surface-soft p-4" key={profile.id}><div className="flex items-start justify-between gap-3"><div><h3 className="font-black">{profile.publicName}</h3><p className="faint mt-1 text-xs">{profile.category} · {profile.positioning}</p></div><a className="btn btn-secondary !min-h-8 !px-2" href={profile.website} target="_blank" rel="noreferrer" aria-label={`Open ${profile.publicName} website`}><ExternalLink size={13} /></a></div><div className="mt-3 space-y-2">{facts.map((fact) => <div className="rounded-lg border border-white/7 bg-black/15 p-2.5" key={fact.id}><div className="flex gap-2"><span className="pill pill-good shrink-0">Verified public fact</span><span className="faint text-[10px]">confidence {fact.confidence}%</span></div><p className="muted mt-2 text-xs leading-5">{fact.statement}</p><div className="mt-2 flex flex-wrap gap-2">{fact.sourceIds.map((sourceId) => { const source = intelligence.dossier.sources.find((item) => item.id === sourceId); return source ? <a className="text-[11px] font-bold text-sky-300 hover:underline" href={source.url} target="_blank" rel="noreferrer" key={source.id}>{source.publisher} <ExternalLink className="inline" size={10} /></a> : null; })}</div></div>)}</div></article>;
            })}</div>
            <div className="mt-4 border-t border-white/8 pt-4"><h3 className="font-black">Simulated move tape</h3>{competitorWorld.moves.length ? <div className="mt-3 space-y-3">{[...competitorWorld.moves].reverse().map((move) => { const profile = competitorWorld.profiles.find((item) => item.id === move.competitorId); return <div className="surface-soft p-4" key={move.id}><div className="flex flex-wrap items-center gap-2"><span className="pill pill-warn">Simulated competitor action</span><span className="pill capitalize">{move.status}</span><span className="faint text-xs">Day {move.simulationDay} · {profile?.publicName}</span>{move.playerResponse && <span className="pill pill-good capitalize">Answered: {move.playerResponse.replaceAll("_", " ")}</span>}</div><p className="muted mt-3 text-sm leading-6">{move.publicSummary}</p><div className="faint mt-2 text-[11px]">Bounded pressure: price {number(move.impact.pricePressure)} · substitution {number(move.impact.substitutionRisk)} · channel {number(move.impact.channelPressure)} · trust {number(move.impact.trustPressure)}</div><div className="mt-3 flex flex-wrap gap-2">{(["differentiate", "match_price", "niche_down", "accelerate", "partner", "ignore"] as const).map((response) => <button className="btn btn-secondary !min-h-8 !px-2 text-[11px] capitalize" disabled={status !== "saved" || Boolean(pendingAgentTurn) || Boolean(move.playerResponse)} onClick={() => command("competitor.respond", { competitorId: move.competitorId, response })} key={response}>{response.replaceAll("_", " ")}</button>)}</div></div>; })}</div> : <p className="muted mt-2 text-sm">No simulated competitor move has become visible yet. Competitors react only after observable signals and cooldowns.</p>}</div>
          </Panel>}
          <Panel title="Market segments" subtitle="Visible figures are hypotheses; research improves confidence without revealing ground truth."><div className="grid gap-3 md:grid-cols-3">{state.market.segments.map((segment) => <button onClick={() => setSelectedSegment(segment.id)} className={cn("surface-soft p-4 text-left", selectedSegment === segment.id && "border-emerald-300/40")} key={segment.id}><div className="font-bold">{segment.label}</div><div className="muted mt-2 text-xs">Observed fit {number(segment.fitSignal)}/100</div><div className="faint mt-2 text-xs">List WTP {money(segment.willingnessToPay)} · cycle {segment.budgetCycleDays}d</div></button>)}</div></Panel><Panel title="Risk register"><div className="grid gap-2">{state.risks.map((risk) => <div className="surface-soft flex items-center justify-between gap-3 p-3" key={risk.id}><div><div className="font-bold text-sm">{risk.title}</div><div className="faint mt-1 text-xs">{risk.domain} · exposure {number(risk.exposure)} · impact {number(risk.impact)}</div></div><span className={cn("pill", risk.status === "realized" ? "pill-bad" : risk.status === "mitigated" ? "pill-good" : "pill-warn")}>{risk.status}</span></div>)}</div></Panel><Panel title="Architecture and posture"><div className="grid gap-2 sm:grid-cols-4">{["concierge", "no_code", "custom", "platform"].map((architecture) => <button key={architecture} disabled={status !== "saved" || state.product.architecture === architecture} className="btn btn-secondary capitalize" onClick={() => command("strategy.architecture.change", { architecture })}>{architecture.replaceAll("_", " ")}</button>)}</div><div className="mt-3 grid gap-2 sm:grid-cols-3">{["smb", "design_partner", "enterprise"].map((strategy) => <button key={strategy} disabled={status !== "saved" || state.meta.strategy === strategy} className="btn btn-secondary capitalize" onClick={() => command("strategy.pivot", { strategy })}>{strategy.replaceAll("_", " ")}</button>)}</div></Panel><Panel title="Capital strategy" subtitle={isV7 ? "This campaign continues through the frozen v7 capital rules." : "Fundraising is a delayed pipeline with diligence risk; a term sheet is not cash until accepted."}><div className="surface-soft flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between"><div><strong className="capitalize">{state.capital.fundraising.replaceAll("_", " ")}</strong><div className="faint mt-1 text-xs">Investor pipeline {number(state.capital.investorPipeline)}/100 · dilution {number(state.capital.dilution)}%</div></div><div className="flex flex-wrap gap-2">{state.capital.fundraising === "none" && <button className="btn btn-primary" disabled={status !== "saved"} onClick={() => command("capital.fundraise", { operation: "start" })}>Start fundraise</button>}{["preparing", "diligence"].includes(state.capital.fundraising) && <button className="btn btn-secondary" disabled={status !== "saved"} onClick={() => command("capital.fundraise", { operation: "cancel" })}>Stop fundraise</button>}{state.capital.fundraising === "term_sheet" && <><button className="btn btn-primary" disabled={status !== "saved"} onClick={() => command("capital.term_sheet", { decision: "accept" })}>Accept $100k / 18%</button><button className="btn btn-secondary" disabled={status !== "saved"} onClick={() => command("capital.term_sheet", { decision: "reject" })}>Reject terms</button></>}</div></div></Panel>{!isV7 && <Panel title="Strategic alternatives" subtitle="These decisions end the independent campaign and create an immutable debrief."><div className="grid gap-2 sm:grid-cols-2"><button className="btn btn-secondary" disabled={status !== "saved" || state.status !== "active"} onClick={() => command("strategy.exit", { ending: "acqui_hire" })}>Accept an acqui-hire</button><button className="btn btn-secondary text-red-200" disabled={status !== "saved" || state.status !== "active"} onClick={() => command("strategy.exit", { ending: "voluntary_shutdown" })}>Controlled shutdown</button></div></Panel>}</Tabs.Content>

        <Tabs.Content value="advanced" className="space-y-4"><Panel title="Deterministic diagnostics"><dl className="grid gap-3 text-sm sm:grid-cols-2"><div className="surface-soft p-3"><dt className="muted text-xs">State version</dt><dd className="mt-1 font-mono">{version}</dd></div><div className="surface-soft p-3"><dt className="muted text-xs">Checksum</dt><dd className="mt-1 break-all font-mono">{checksum}</dd></div><div className="surface-soft p-3"><dt className="muted text-xs">RNG state / draws</dt><dd className="mt-1 font-mono">{state.rng.state} / {state.rng.draws}</dd></div><div className="surface-soft p-3"><dt className="muted text-xs">Scheduled effects</dt><dd className="mt-1 font-mono">{state.scheduledEffects.length}</dd></div></dl></Panel><Panel title="Client projection" subtitle="Hidden market truth is removed before this state reaches the browser."><pre className="max-h-[480px] overflow-auto rounded-xl bg-black/30 p-4 text-[11px] leading-5 text-slate-300">{JSON.stringify({ ...state, legacy: state.legacy ? { sourceVersion: state.legacy.sourceVersion, sourceState: "[preserved in cloud snapshot]" } : undefined }, null, 2)}</pre></Panel></Tabs.Content>
      </main>

      <aside className="space-y-4">
        <Panel title="Decision Studio" subtitle={selected ? `Causal issue: ${selected.title}` : "Select an open issue"}>
          <label className="label" htmlFor="targetSegment">Target segment</label><select id="targetSegment" className="input" value={selectedSegment} onChange={(event) => setSelectedSegment(event.target.value)}>{state.market.segments.map((segment) => <option key={segment.id} value={segment.id}>{segment.label}</option>)}</select>
          <div className="mt-4 border-t border-white/8 pt-4"><div className="flex items-center gap-2 text-sm font-black"><FlaskConical size={15} className="text-emerald-300" />Research design</div><div className="mt-3 grid grid-cols-2 gap-2">
            <select aria-label="Research question" className="input" value={researchQuestion} onChange={(event) => setResearchQuestion(event.target.value as typeof researchQuestion)}><option value="severity">Problem severity</option><option value="workflow">Workflow behavior</option><option value="budget">Budget proof</option><option value="buyer">Buyer mapping</option></select>
            <select aria-label="Research method" className="input" value={researchMethod} onChange={(event) => setResearchMethod(event.target.value as typeof researchMethod)}><option value="interview">Interview</option><option value="observation">Observation</option><option value="proposal">Proposal</option><option value="survey">Survey</option></select>
            <select aria-label="Research sample" className="input" value={researchSample} onChange={(event) => setResearchSample(event.target.value as typeof researchSample)}><option value="cold_targeted">Cold targeted</option><option value="existing_users">Existing users</option><option value="warm_network">Warm network</option><option value="convenience">Convenience</option></select>
            <input aria-label="Research sample size" className="input" type="number" min="1" max="30" value={researchCount} onChange={(event) => setResearchCount(Number(event.target.value))} />
            <select aria-label="Action intensity" className="input col-span-2" value={actionIntensity} onChange={(event) => setActionIntensity(event.target.value as typeof actionIntensity)}><option value="sustainable">Sustainable intensity</option><option value="hard">Hard push</option><option value="crunch">Crunch</option></select>
          </div><button disabled={!selected || status !== "saved"} className="btn btn-primary mt-2 w-full" onClick={() => isV7 ? command("problem.action.commit", { problemId: selected?.id, kind: "research", intensity: actionIntensity, researchDesign: { question: researchQuestion, sample: researchSample, method: researchMethod, count: researchCount } }) : command("research.run", { problemId: selected?.id, segmentId: selectedSegment, design: { question: researchQuestion, sample: researchSample, method: researchMethod, count: researchCount }, intensity: actionIntensity })}>Commit research design</button></div>
          <div className="mt-4 border-t border-white/8 pt-4"><div className="flex items-center gap-2 text-sm font-black"><Boxes size={15} className="text-sky-300" />Product work</div><select aria-label="Product capability" className="input mt-3" value={capabilityChoice?.id ?? ""} onChange={(event) => setSelectedCapability(event.target.value)}>{state.product.capabilities.filter((capability) => capability.status === "backlog").map((capability) => <option key={capability.id} value={capability.id}>{capability.label} · effort {capability.effort}</option>)}</select><select aria-label="Product approach" className="input mt-2" value={productApproach} onChange={(event) => setProductApproach(event.target.value as typeof productApproach)}><option value="prototype">Prototype — faster, less robust</option><option value="production">Production — slower, lower risk</option><option value="accept_debt">Ship with debt — fastest, delayed downside</option></select>{capabilityChoice && <button disabled={!selected || status !== "saved"} className="btn btn-secondary mt-2 w-full" onClick={() => isV7 ? command("problem.action.commit", { problemId: selected?.id, kind: "build", intensity: actionIntensity }) : command("product.plan", { capabilityId: capabilityChoice.id, approach: productApproach, intensity: actionIntensity })}>Commit {capabilityChoice.label}</button>}</div>
          <div className="mt-4 grid gap-2"><button disabled={!selected || status !== "saved"} className="btn btn-secondary !justify-start" onClick={() => isV7 ? command("problem.action.commit", { problemId: selected?.id, kind: "service_offer", intensity: actionIntensity }) : command("experiment.start", { problemId: selected?.id, segmentId: selectedSegment, kind: "paid_pilot", budget: 25 })}><Sparkles size={15} />Run a $25 paid-pilot experiment</button>{!isV7 && <button disabled={status !== "saved"} className="btn btn-secondary !justify-start" onClick={() => command("account.manage", { operation: "source", segmentId: selectedSegment })}><Network size={15} />Source one account</button>}</div>
        </Panel>
        {!isV7 && <Panel title="Capacity portfolio" subtitle="Allocation now changes execution speed and quality by work domain."><div className="grid grid-cols-2 gap-2">{[
          ["Discover", { research: 50, product: 15, sales: 20, operations: 15 }], ["Build", { research: 15, product: 55, sales: 15, operations: 15 }],
          ["Sell", { research: 15, product: 15, sales: 55, operations: 15 }], ["Stabilize", { research: 10, product: 20, sales: 20, operations: 50 }],
        ].map(([label, allocation]) => <button key={label as string} className="btn btn-secondary" disabled={status !== "saved"} onClick={() => command("planning.capacity.allocate", allocation)}>{label as string}</button>)}</div><div className="faint mt-3 text-xs">Current: R{state.founder.allocation.research} · P{state.founder.allocation.product} · S{state.founder.allocation.sales} · O{state.founder.allocation.operations}</div></Panel>}
        {!isV7 && <Panel title="People and cash controls"><div className="grid grid-cols-2 gap-2"><select aria-label="Engagement mode" className="input" value={peopleMode} onChange={(event) => setPeopleMode(event.target.value as typeof peopleMode)}><option value="contract">Contract</option><option value="hire">Hire</option><option value="advisor">Advisor</option></select><select aria-label="People role" className="input" value={peopleRole} onChange={(event) => setPeopleRole(event.target.value as typeof peopleRole)}><option value="engineer">Engineer</option><option value="product">Product</option><option value="sales">Sales</option><option value="operations">Operations</option></select><input aria-label="People budget" className="input" type="number" min="0" value={peopleBudget} onChange={(event) => setPeopleBudget(Number(event.target.value))} /><button className="btn btn-secondary" disabled={status !== "saved"} onClick={() => command("people.engage", { operation: peopleMode, role: peopleRole, budget: peopleBudget })}>Start workflow</button><input aria-label="Finance amount" className="input" type="number" min="0" value={financeAmount} onChange={(event) => setFinanceAmount(Number(event.target.value))} /><button className="btn btn-secondary" disabled={status !== "saved" || state.finance.personalCash < financeAmount} onClick={() => command("finance.manage", { operation: "founder_injection", amount: financeAmount })}>Founder loan</button><button className="btn btn-secondary" disabled={status !== "saved"} onClick={() => command("finance.manage", { operation: "cut_cost", amount: financeAmount })}>Cut verified cost</button><button className="btn btn-secondary" disabled={status !== "saved" || state.finance.accountsReceivable <= 0} onClick={() => command("finance.manage", { operation: "collect_invoice", amount: financeAmount })}>Collect AR</button></div></Panel>}
        {!isV7 && actionableAccount?.stage === "negotiation" && <Panel title="Deal desk" subtitle="Terms improve conversion by transferring cost, cash timing, and risk into future obligations."><div className="grid grid-cols-2 gap-2"><input aria-label="Monthly price" className="input" type="number" min="1" value={dealPrice} onChange={(event) => setDealPrice(Number(event.target.value))} /><input aria-label="Contract months" className="input" type="number" min="1" max="36" value={dealMonths} onChange={(event) => setDealMonths(Number(event.target.value))} /><select aria-label="Payment terms" className="input" value={paymentTerms} onChange={(event) => setPaymentTerms(Number(event.target.value) as typeof paymentTerms)}><option value={0}>Prepaid / due now</option><option value={15}>Net 15</option><option value={30}>Net 30</option><option value={60}>Net 60</option></select><select aria-label="Onboarding mode" className="input" value={onboardingMode} onChange={(event) => setOnboardingMode(event.target.value as typeof onboardingMode)}><option value="self_serve">Self-serve</option><option value="guided">Guided</option><option value="custom">Custom</option></select><select aria-label="Support SLA" className="input" value={supportSla} onChange={(event) => setSupportSla(Number(event.target.value) as typeof supportSla)}><option value={8}>8-hour SLA</option><option value={24}>24-hour SLA</option><option value={72}>72-hour SLA</option></select><select aria-label="Data terms" className="input" value={dataTerms} onChange={(event) => setDataTerms(event.target.value as typeof dataTerms)}><option value="standard">Standard data terms</option><option value="dpa">DPA</option><option value="enterprise">Enterprise controls</option></select></div><label className="mt-3 flex items-center gap-2 text-xs"><input type="checkbox" checked={dealPrepay} onChange={(event) => setDealPrepay(event.target.checked)} />Offer 8% discount for term prepayment</label><button className="btn btn-primary mt-3 w-full" disabled={status !== "saved"} onClick={() => command("contract.negotiate", { accountId: actionableAccount.id, price: dealPrice, contractMonths: dealMonths, discountForPrepay: dealPrepay, paymentTermsDays: paymentTerms, onboardingMode, supportSlaHours: supportSla, dataTerms })}>Submit term sheet</button></Panel>}
        {actionableAccount && <Panel title="Pipeline focus" subtitle={`${actionableAccount.name} · ${actionableAccount.stage}`}><button className="btn btn-primary w-full" disabled={status !== "saved" || state.scheduledEffects.some((effect) => effect.type === "account_followup" && effect.sourceId === actionableAccount.id)} onClick={() => command("account.manage", { operation: "advance", accountId: actionableAccount.id })}>Commit next follow-up</button></Panel>}
        <Panel title="Active commitments" subtitle={`${number(attention, 2)}× attention load`}><div className="space-y-2">{active.length ? active.map((action) => <div className="surface-soft p-3" key={action.id}><div className="text-sm font-bold">{action.title}</div><div className="muted mt-1 text-xs">{number(action.remainingWork, 1)} work days · {action.intensity}</div><button className="mt-2 text-xs font-bold text-red-300" disabled={status !== "saved"} onClick={() => command("problem.action.cancel", { actionId: action.id })}>Cancel · sunk cost remains</button></div>) : <p className="muted text-sm">No commitments are active.</p>}</div></Panel>
      </aside></div>
    </Tabs.Root></div>

    <div className="fixed inset-x-0 bottom-[61px] z-30 border-t border-white/9 bg-[#08131d]/94 p-3 backdrop-blur-xl lg:bottom-0 lg:left-60"><div className="container-page flex items-center justify-between gap-4"><div className="hidden min-w-0 sm:block"><div className={cn("text-sm font-black", attention > 1.15 ? "text-red-300" : "text-emerald-300")}>{attention > 1.15 ? "Overcommitted" : isV7 ? "Frozen v7 engine active" : "Causal engine active"}</div><div className="muted truncate text-xs">Next action completion, scheduled consequence, deadline, or month close</div></div><button className="btn btn-primary w-full sm:w-auto" disabled={status !== "saved" || Boolean(state.pendingEvent) || state.status !== "active"} onClick={() => isV7 ? command("operations.advance", {}) : command("operations.advance_to_decision", { maxDays: 14 })}>{status === "saving" ? <LoaderCircle className="animate-spin" size={16} /> : <Cloud size={16} />}Advance to next decision <ArrowRight size={16} /></button></div></div>
  </div>;
}
